-- 12.11.2026 — головний віджет: гармонійна сітка, розділи платформи, видима кнопка.
--
-- Що змінилось проти попереднього вигляду:
--   * одна система: відступ 20 px, волосяна лінія 1 px, радіус 12 px, одна шкала шрифтів;
--   * лого — лише в шапці, без повторів усередині видів;
--   * чотири плитки розділів платформи (трекери, сервіси, розвиток, обране) —
--     відкривають WEB_PLATFORM_URL; у сценарії стоїть маркер `__PLATFORM__`,
--     адресу підставляє бот (`applyPlatformUrl`);
--   * «Назад до старту» — кнопка 40 px, а не дрібний текст;
--   * види з м'яким входом (animation) і віддачею на натиск.
--
-- Розмір: 8068 байт сирого, 2853 байт після zlib-9 (межа 4096).

UPDATE "bot_scenarios"
SET
  widget_html = '<style>*{box-sizing:border-box}body{margin:0;background:#faf7f0;color:#171d26;font:14px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}.s{height:430px;display:flex;flex-direction:column;position:relative;overflow:hidden;background:#faf7f0}.w{display:flex;align-items:center;gap:9px;padding:14px 20px;border-bottom:1px solid #e7ddca}.l{width:28px;height:28px;flex:0 0 28px;border-radius:50%;overflow:hidden;box-shadow:0 1px 2px #171d261a,0 0 0 1px #ddcfae}.l svg{width:28px;height:28px;display:block}.n b{display:block;font-size:11.5px;letter-spacing:2.6px;font-weight:700;color:#12181f;line-height:1.2}.n s{display:block;font-size:7.5px;letter-spacing:1.8px;color:#a5946f;text-decoration:none;margin-top:2px}.v{position:absolute;inset:57px 0 0;display:flex;flex-direction:column;animation:in .22s ease both}[hidden]{display:none}@keyframes in{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}.p{flex:1;display:flex;flex-direction:column;padding:16px 20px 0;min-height:0}.f{display:flex;align-items:center;justify-content:space-between;margin:0 20px;padding:8px 0 10px;border-top:1px solid #e7ddca;font-size:8px;letter-spacing:1.7px;color:#a49a86;text-transform:uppercase}.f em{font-style:normal;font-variant-numeric:tabular-nums;letter-spacing:1.2px}h1,h2{margin:0;font-family:ui-serif,Georgia,serif;font-weight:600;color:#12181f;letter-spacing:-.3px}h1{font-size:30px;line-height:1.05}h1 span{display:block;font-size:20px;font-style:italic;font-weight:400;color:#8b8271;margin-top:4px;letter-spacing:0}h2{font-size:27px;line-height:1.1}.lb{font-size:8px;letter-spacing:1.9px;color:#a5946f;text-transform:uppercase;margin:16px 0 7px}.tg{display:grid;grid-template-columns:1fr 1fr;gap:8px}.t{display:flex;flex-direction:column;justify-content:space-between;min-height:58px;padding:9px 10px;border:1px solid #e7ddca;border-radius:12px;background:#fffdf8;color:#1b2430;font:inherit;text-align:left;transition:transform .12s ease,background .12s ease}.t:active{transform:scale(.97);background:#f6efe0}.t i{display:flex;align-items:center;justify-content:space-between}.t svg{color:#b0812c}.t em{font-style:normal;font-size:12px;color:#b3a488;line-height:1}.t b{font-size:12.5px;font-weight:600;letter-spacing:.1px;line-height:1.2}.rs{margin-top:auto}.r{display:flex;align-items:center;justify-content:space-between;width:100%;padding:11px 0;border:0;border-top:1px solid #e7ddca;background:none;color:inherit;font:inherit;text-align:left}.r:last-of-type{border-bottom:1px solid #e7ddca}.r:active{opacity:.55}.r b{font-size:13.5px;font-weight:600}.c{color:#c0b192;font-size:15px;line-height:1}.bk{display:flex;align-items:center;justify-content:center;gap:7px;width:100%;height:40px;margin:14px 0 8px;border:1px solid #ddcfae;border-radius:12px;background:#fffdf8;color:#8a6a1f;font:inherit;font-size:13px;font-weight:600;transition:transform .12s ease,background .12s ease}.bk:active{transform:scale(.98);background:#f3ead8}.st{margin:10px 0 0;font-family:ui-serif,Georgia,serif;font-size:19px;line-height:1.45;color:#2b333e;max-width:23ch}.rule{height:1px;background:#e7ddca;margin:13px 0}.sp{flex:1}.mid{align-items:center;text-align:center}.mid h2{margin-top:2px}.mid .st{text-align:center;max-width:20ch;font-size:17px;color:#5d6672;margin-top:8px}</style><div class="s"><div class="w"><span class="l"><svg viewBox="0 0 64 64" aria-hidden="true"><defs><radialGradient id="pa" cx="36%" cy="26%" r="80%"><stop offset="0" stop-color="#d3a068"/><stop offset=".36" stop-color="#a96c2c"/><stop offset=".74" stop-color="#713a0e"/><stop offset="1" stop-color="#3f1c03"/></radialGradient><linearGradient id="pb" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fdf1d6"/><stop offset="1" stop-color="#dcb886"/></linearGradient></defs><circle cx="32" cy="32" r="31" fill="url(#pa)"/><clipPath id="pc"><circle cx="32" cy="32" r="29.4"/></clipPath><g clip-path="url(#pc)"><path d="M12 14c8 3 12 6 18 11m8 5c5 4 8 7 14 9" stroke="#f7e6c6" stroke-width="3" stroke-linecap="round" fill="none" opacity=".5"/><g fill="none" stroke-linecap="round"><g stroke="#2f1402" stroke-width="7" opacity=".6"><path d="M14 19 45 42M19 47 47 18M11 32 30 51M32 11 51 30"/></g><g stroke="url(#pb)" stroke-width="3.4"><path d="M14 19 45 42M19 47 47 18M11 32 30 51M32 11 51 30"/></g></g><g fill="#fdf5e6" opacity=".85"><ellipse cx="23" cy="24" rx="1" ry=".7"/><ellipse cx="35" cy="20" rx=".9" ry=".6"/><ellipse cx="43" cy="28" rx="1" ry=".7"/><ellipse cx="27" cy="34" rx=".9" ry=".6"/><ellipse cx="38" cy="39" rx="1" ry=".7"/><ellipse cx="22" cy="44" rx=".9" ry=".6"/><ellipse cx="33" cy="48" rx=".9" ry=".6"/><ellipse cx="17" cy="32" rx=".9" ry=".6"/><ellipse cx="47" cy="35" rx=".9" ry=".6"/></g></g><circle cx="32" cy="32" r="29.5" fill="none" stroke="#f8e4c0" stroke-opacity=".2"/></svg></span><span class="n"><b>ПАЛЯНИЦЯ</b><s>ДІЛОВА ПЛАТФОРМА</s></span></div><div class="v" id="v-start"><div class="p"><h1>Ділова платформа<span>для Своїх</span></h1><p class="lb">Розділи платформи</p><div class="tg"><a class="t" data-u="trackers" href="#"><i><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg><em>↗</em></i><b>Трекери</b></a><a class="t" data-u="services" href="#"><i><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg><em>↗</em></i><b>Сервіси</b></a><a class="t" data-u="assessments" href="#"><i><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M4 18 10 12l4 3 6-8"/></svg><em>↗</em></i><b>Розвиток</b></a><a class="t" data-u="favorites" href="#"><i><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M12 20s-7-4.4-7-9a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 4.6-7 9-7 9Z"/></svg><em>↗</em></i><b>Обране</b></a></div><div class="rs"><button class="r" data-k="about"><b>Про платформу</b><span class="c">›</span></button><button class="r" data-k="contacts"><b>Контакти</b><span class="c">›</span></button></div></div><div class="f"><span>Старт</span><em>01 / 03</em></div></div><div class="v" id="v-about" hidden><div class="p"><h2>Про платформу</h2><div class="rule"></div><p class="st">ПАЛЯНИЦЯ — ділова платформа для Своїх.</p><div class="sp"></div><button class="bk" data-k="start">← Назад до старту</button></div><div class="f"><span>Про платформу</span><em>02 / 03</em></div></div><div class="v" id="v-contacts" hidden><div class="p mid"><div class="sp"></div><h2>Контакти</h2><div class="rule" style="width:56px;margin:12px auto 0"></div><p class="st">Зв’язок з адміністратором.</p><div class="sp"></div><button class="bk" data-k="start">← Назад до старту</button></div><div class="f"><span>Контакти</span><em>03 / 03</em></div></div></div><script>var W=window.TelegramWidget,V={},PL="__PLATFORM__";if(W){["start","about","contacts"].forEach(function(k){V[k]=document.getElementById("v-"+k)});function show(v){v=V[v]?v:"start";for(var k in V)V[k].hidden=k!==v}function draw(){var s={};try{s=JSON.parse(W.chatData||"{}")}catch(e){}show(s.v)}W.onEvent("chatDataChanged",draw);document.querySelectorAll("[data-k]").forEach(function(b){b.onclick=function(){W.request(b.getAttribute("data-k")).catch(function(){})}});document.querySelectorAll("[data-u]").forEach(function(a){if(!/^https?:/.test(PL)){a.style.opacity=.4;return}a.onclick=function(e){e.preventDefault();W.openLink(PL.replace(/\/$/,"")+"/"+a.getAttribute("data-u")).catch(function(){})}});draw()}</script>',
  widget_data = '{"v":"start"}',
  updated_at = datetime('now')
WHERE lookup = '/start';
